envelop.script:
function MessageArea() {
}
MessageArea.init = function() {
};
MessageArea.hide = function() {
	$(window).off("scroll");
	$(window).off("keypress");
	$(window).off("keydown");
	$("div#message_area div.btn div.btns").empty();
	$("div#message_area div.btn div.btns").hide();
	$("div#message_area input.confirm").off("click");
	$("div#message_area input.cancle").off("click");
	$("div#message_area").hide();
};
MessageArea.alert = function(out, callback) {
	MessageArea.init();
	$("div#message_area").css("top", $(window).scrollTop());
	$(window).scroll(function() {
		$("div#message_area").css("top", $(window).scrollTop());
	});
	$("div#message_area div.confirm").hide();
	$("div#message_area div.btn div.btns").hide();
	$("div#message_area ul.alert").empty();
	if(out &amp;&amp; out != null &amp;&amp; Array.isArray(out)) {
		for(var i = 0; i &lt; out.length; i++) {
			if(out[i].msg &amp;&amp; out[i].msg != null) {
				$("div#message_area ul.alert").append("&lt;li>" + out[i].msg + "&lt;/li>")
			} else {
				$("div#message_area ul.alert").append("&lt;li>" + out[i] + "&lt;/li>")
			}
		}
	} else {
		$("div#message_area ul.alert").append("&lt;li>" + out + "&lt;/li>")
	}
	$("div#message_area input.cancle").hide();
	$("div#message_area input.confirm").off("click");
	$("div#message_area input.cancle").off("click");
	$("div#message_area input.confirm").click(function() {
		MessageArea.hide();
		if(callback) {
			callback(out);
		}
	});
	$(window).off("keydown");
	$(window).keydown(function(e) {
		if(e.which == 13 || e.which == 32 || e.which == 27) {
			MessageArea.hide();
			if(callback) {
				callback(out);
			}
			e.preventDefault();
			return false;
		}
    });
	$("div#message_area ul.alert").show();
	$("div#message_area").show();
	$("div#message_area input.confirm").show();
	$("div#message_area input.confirm").focus();
};
MessageArea.confirm = function(msg, callback, cancleCallback) {
	MessageArea.init();
	$("div#message_area").css("top", $(window).scrollTop());
	$(window).scroll(function() {
		$("div#message_area").css("top", $(window).scrollTop());
	});
	$("div#message_area ul.alert").hide();
	$("div#message_area div.btn div.btns").hide();

	$("div#message_area div.confirm").empty();
	$("div#message_area div.confirm").append(msg);

	$("div#message_area input.confirm").off("click");
	$("div#message_area input.confirm").click(function() {
		MessageArea.hide();
		if(callback) {
			callback();
		}
	});
	$(window).off("keydown");
	$(window).keydown(function(e) {
		if(e.which == 13 || e.which == 32 || e.which == 27) {
			MessageArea.hide();
			if(callback) {
				callback();
			}
			e.preventDefault();
			return false;
		}
    });
	$("div#message_area input.cancle").off("click");
	$("div#message_area input.cancle").click(function() {
		MessageArea.hide();
		if(cancleCallback) {
			cancleCallback();
		}
	});
	$(window).off("keydown");
	$(window).keydown(function(e) {
		if(e.keyCode == 27) {
			MessageArea.hide();
			if(cancleCallback) {
				cancleCallback();
			}
			e.preventDefault();
			return false;
		}
    });
	$("div#message_area input.cancle").show();
	$("div#message_area input.confirm").show();

	$("div#message_area div.confirm").show();
	$("div#message_area").show();
	$("div#message_area input.confirm").focus();
};

MessageArea.message = function(msg, btns) {
	MessageArea.init();
	$("div#message_area").css("top", $(window).scrollTop());
	$(window).scroll(function() {
		$("div#message_area").css("top", $(window).scrollTop());
	});
	$("div#message_area ul.alert").hide();

	$("div#message_area div.confirm").empty();

	if(msg &amp;&amp; msg != null) {
		if(Array.isArray(msg)) {
			$("div#message_area ul.alert").empty();
			for(var i = 0; i &lt; msg.length; i++) {
				if(msg[i].msg &amp;&amp; msg[i].msg != null) {
					$("div#message_area ul.alert").append("&lt;li>" + msg[i].msg + "&lt;/li>")
				} else {
					$("div#message_area ul.alert").append("&lt;li>" + msg[i] + "&lt;/li>")
				}
			}
			$("div#message_area ul.alert").show();
		} else {
			$("div#message_area div.confirm").append(msg);
		}
	}

	$("div#message_area input.confirm").off("click");
	$("div#message_area input.cancle").off("click");

	$("div#message_area input.confirm").hide();
	$("div#message_area input.cancle").hide();
	$("div#message_area div.btn div.btns").empty();
	if(btns) {
		for(var i = 0; i &lt; btns.length; i++) {
			var result = $("div#message_area div.btn div.btns").append("&lt;input type=\"button\" value=\"" + btns[i].label + "\" class=\"graha " + btns[i].className + "\" />");
			if(btns[i].callback) {
				result.children().last().click(
					{
						callback: btns[i].callback,
						parameters: btns[i].parameters
					},
					function(event) {
						event.data.callback(event.data.parameters);
					}
				);
			}
		}
	}
	$(window).off("keydown");
	if(btns) {
		$(window).keydown(function(e) {
			for(var i = 0; i &lt; btns.length; i++) {
				if(btns[i].shortcut &amp;&amp; btns[i].callback) {
					if(Array.isArray(btns[i].shortcut)) {
						for(var x = 0; x &lt; btns[i].shortcut.length; x++) {
							if(MessageArea.shortcut(e, btns[i].shortcut[x])) {
								MessageArea.hide();
								btns[i].callback(btns[i].parameters);
								e.preventDefault();
								return false;
							}
						}
					} else if(MessageArea.shortcut(e, btns[i].shortcut[x])) {
						MessageArea.hide();
						btns[i].callback(btns[i].parameters);
						e.preventDefault();
						return false;
					}
				}
			}
		});
    }
    if(btns) {
		$("div#message_area div.btn div.btns").show();
	}
	$("div#message_area div.confirm").show();
	$("div#message_area").show();
	$("div#message_area div.confirm").focus();
};
MessageArea.shortcut = function(event, item) {
	if(
		typeof(item) == "number" &amp;&amp;
		(
			event.keyCode == item ||
			event.keyCode == String.fromCharCode(item).toLowerCase().charCodeAt(0) ||
			event.keyCode == String.fromCharCode(item).toUpperCase().charCodeAt(0)
		)
	) {
		return true;
	} else if(
		typeof(item) == "string" &amp;&amp;
		item.length == 1 &amp;&amp;
		(
			event.keyCode == item.charCodeAt(0) ||
			event.keyCode == item.toLowerCase().charCodeAt(0) ||
			event.keyCode == item.toUpperCase().charCodeAt(0)
		)
	) {
		return true;
	} else if(
		typeof(item) == "string" &amp;&amp;
		item.toLowerCase() == "space" &amp;&amp;
		event.keyCode == 32
	) {
		return true;
	} else if(
		typeof(item) == "string" &amp;&amp;
		item.toLowerCase() == "enter" &amp;&amp;
		event.which == 13
	) {
		return true;
	} else if(
		typeof(item) == "string" &amp;&amp;
		item.toLowerCase() == "esc" &amp;&amp;
		event.which == 27
	) {
		return true;
	}
	return false;
};

function LoginArea() {

}
LoginArea.hide = function(callback, cancleCallback) {
	$("div#login_area").hide();
	$(window).off("scroll");
	$(window).off("keypress");
	$(window).off("keydown");
};
LoginArea.showCancle = function() {
	$("div#login_area fieldset.login input.cancle").show();
};
LoginArea.hideCancle = function() {
	$("div#login_area fieldset.login input.cancle").hide();
};
LoginArea.show = function(options, callback, cancleCallback) {
	if(options &amp;&amp; options != null) {
		if(options.idFieldName &amp;&amp; options.idFieldName != null) {
			$("div#login_area fieldset.login input#id000").attr("name", options.idFieldName);
		}
		if(options.idFieldValue &amp;&amp; options.idFieldValue != null) {
			$("div#login_area fieldset.login input#id000").val(options.idFieldValue);
		}
		if(options.pwdFieldName &amp;&amp; options.pwdFieldName != null) {
			$("div#login_area fieldset.login input#pwd000").attr("name", options.pwdFieldName);
		}
		if(options.actionUrl &amp;&amp; options.actionUrl != null) {
			$("form#LoginFrm").attr("action", options.actionUrl);
		}
		if(options.params &amp;&amp; options.params != null) {
			window.setTimeout(function() {
				if($("div#login_area fieldset.login").length > 0) {
					var target = $("div#login_area fieldset.login")[0];
					for(var i = 0; i &lt; options.params.length; i++) {
						var hidden = document.createElement("input");
						hidden.setAttribute("type", "hidden");
						hidden.setAttribute("name", options.params[i].name);
						hidden.setAttribute("value", options.params[i].value);
						target.appendChild(hidden);
					}
				}
			}, 0);
		}
	}
	$("div#login_area").css("top", $(window).scrollTop());
	$(window).scroll(function() {
		$("div#login_area").css("top", $(window).scrollTop());
	});
	$("div#login_area fieldset.login input.pwd").each(function() {
		if($("div#login_area fieldset.login input#showpwd").prop("checked")) {	
			$(this).prop("type", "text");
		} else {
			$(this).prop("type", "password");
		}
	});
	if(cancleCallback) {
		LoginArea.attach(callback, cancleCallback);
	} else {
		LoginArea.attach(callback);
	}
	$("div#login_area fieldset.login div.alert").hide();
	$("div#login_area").show();
	$("div#login_area fieldset.login input#id000").focus();
};
LoginArea.login = function(callback, cancleCallback) {
	var username = $("div#login_area fieldset.login input#id000").val();
	var password = $("div#login_area fieldset.login input#pwd000").val();
	if(username == null || username == "") {
		LoginArea.alert("!!!아이디를 입력해 주세요!!!");
	} else if(password == null || password == "") {
		LoginArea.alert("!!!패스워드를 입력해 주세요!!!");
	} else {
		try {
			var form = null;
			if($("form#LoginFrm").length > 0) {
				form = $("form#LoginFrm")[0];
				var formData = new FormData(form);
				var url = $("form#LoginFrm").attr("action");
				$.ajax({
					url: url,
					processData: false,
					contentType: false,
					type: 'POST',
					enctype: 'multipart/form-data',
					data: formData,
					headers: {
						"x-graha-requested-with": "XMLHttpRequest"
					}
				}).then(function(result, textStatus, jqXHR) {
					if(callback) {
						callback();
					}
					LoginArea.hide();
				}).fail(function(jqXHR, textStatus, errorThrown) {
					if(jqXHR.status == 401) {
						var loginErrorMessage = jqXHR.getResponseHeader("x-graha-login-error-message");
						var loginErrorNextPage = jqXHR.getResponseHeader("x-graha-login-error-next-page");
						if(loginErrorMessage &amp;&amp; loginErrorMessage != null &amp;&amp; loginErrorMessage != "") {
							LoginArea.hide();
							MessageArea.alert(
								decodeURIComponent(loginErrorMessage),
								function() {
									if(loginErrorNextPage &amp;&amp; loginErrorNextPage != null &amp;&amp; loginErrorNextPage != "") {
										location.href = decodeURIComponent(loginErrorNextPage);
									} else {
										location.reload();
									}
								}
							);
						} else {
							LoginArea.alert("!!!아이디/패스워드가 정확하지 않습니다!!!");
						}
					} else {
						LoginArea.alert("!!!원인을 알 수 없는 에러가 발생했습니다!!!");
					}
				});
			} else {
				LoginArea.alert("!!!원인을 알 수 없는 에러가 발생했습니다!!!");
			}
		} catch (error) {
			LoginArea.alert("!!!패스워드가 정확하지 않습니다!!!");
		}
	}
};
LoginArea.attach = function(callback, cancleCallback) {
	$("div#login_area fieldset.login input.cancle").off("click");
	if(cancleCallback) {
		LoginArea.showCancle();
		$("div#login_area fieldset.login input.cancle").click(function() {
			LoginArea.hide();
			if(cancleCallback &amp;&amp; typeof(cancleCallback) == "function") {
				cancleCallback();
			}
		});
		$(window).off("keydown");
		$(window).keydown(function(e) {
			if(e.keyCode == 27) {
				LoginArea.hide();
				if(cancleCallback &amp;&amp; typeof(cancleCallback) == "function") {
					cancleCallback();
				}
				e.preventDefault();
				return false;
			}
		});
	}
	$("div#login_area fieldset.login input#showpwd").off("click");
	$("div#login_area fieldset.login input#showpwd").click(function() {
		$("div#login_area fieldset.login input.pwd").each(function() {
			if($("div#login_area fieldset.login input#showpwd").prop("checked")) {	
				$(this).prop("type", "text");
			} else {
				$(this).prop("type", "password");
			}
		});
	});
	$("div#login_area fieldset.login input.confirm").off("click");
	$("div#login_area fieldset.login input.confirm").click(function() {
		LoginArea.login(callback, cancleCallback);
	});
	$(window).off("keypress");
	$(window).keypress(function(e) {
		if(e.which == 13) {
			LoginArea.login(callback, cancleCallback);
			e.preventDefault();
			return false;
		}
    });
};
LoginArea.alert = function(msg) {
	$("div#login_area fieldset.login div.alert").empty();
	$("div#login_area fieldset.login div.alert").append(msg);
	$("div#login_area fieldset.login div.alert").show();
};
LoginArea.check_login = function(frm) {
	return false;
};
